CREATE TABLE `user_basic_profile` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `nickname` varchar(64) NOT NULL,
  `bio` varchar(255) NOT NULL,
  `grade_label` varchar(32) NOT NULL,
  `pronouns` varchar(32) NOT NULL,
  `gender` varchar(16) DEFAULT NULL COMMENT '性别 male/female',
  `interest_tags` json DEFAULT NULL COMMENT '兴趣标签列表（JSON数组格式，如 ["摄影","篮球","阅读"]）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `height` int DEFAULT NULL,
  `education_level` varchar(16) DEFAULT NULL,
  `relationship_status` varchar(16) DEFAULT NULL,
  `hometown_province` varchar(32) DEFAULT NULL,
  `hometown_city` varchar(32) DEFAULT NULL,
  `future_city` varchar(32) DEFAULT NULL,
  `future_plan_tags` json DEFAULT (json_array()),
  `photo_gallery` json DEFAULT (json_array()),
  `half_body_photo_url` varchar(512) DEFAULT NULL,
  `personal_video_url` varchar(512) DEFAULT NULL,
  `profile_background_url` varchar(512) DEFAULT NULL,
  `email_verified` tinyint(1) NOT NULL DEFAULT '0',
  `id_card_verified` tinyint(1) NOT NULL DEFAULT '0',
  `version` bigint NOT NULL DEFAULT '0' COMMENT '乐观锁版本号（Task 2.1.1）',
  `occupation` varchar(64) DEFAULT NULL COMMENT '职业（展示文本）',
  `income_range` varchar(16) DEFAULT NULL COMMENT '月收入档位：3k-8k/8k-15k/15k-30k/30k+',
  `personality_tags` json DEFAULT NULL COMMENT '性格标签（JSON 数组，空数组由应用层默认）',
  `mbti` varchar(8) DEFAULT NULL COMMENT 'MBTI 人格类型',
  `expected_partner` varchar(255) DEFAULT NULL COMMENT '期待的人物画像描述',
  `birth_year` int DEFAULT NULL COMMENT '出生年份（年龄=当前年-birth_year）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_basic_profile_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=230 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
