  `audit_remark` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '审核备注（拒绝原因等）',
  `auditor_id` bigint unsigned DEFAULT NULL COMMENT '审核人用户 ID',
  `audited_at` datetime DEFAULT NULL COMMENT '审核时间',
  `category` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'GENERAL' COMMENT '业务分类：GENERAL/AVATAR/POST/VOICE/VIDEO/ID_CARD（ID_CARD 仅本人/ADMIN 可读）',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_media_asset_url` (`url`),
  KEY `idx_media_user` (`user_id`),
  KEY `idx_media_type` (`type`),
  KEY `idx_media_user_type` (`user_id`,`type`),
  KEY `idx_media_asset_user_type` (`user_id`,`type`),
  KEY `idx_media_audit_status_created` (`audit_status`,`created_at`),
  KEY `idx_media_user_audit` (`user_id`,`audit_status`),
  KEY `idx_media_asset_category` (`category`)
) ENGINE=InnoDB AUTO_INCREMENT=1860 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
